<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\Model; use Pterodactyl\Models\User; use Illuminate\Database\Eloquent\Relations\BelongsTo; class StaffFeedback extends Model { public const RESOURCE_NAME = 'staff_feedback'; public const HAPPY = 'happy'; public const OKAY = 'okay'; public const SAD = 'sad'; public const MOODS = [self::HAPPY, self::OKAY, self::SAD]; public const MAX_NOTE = 1000; protected $table = 'dezerx_staff_feedback'; protected $guarded = ['id']; protected $casts = [ 'request_id' => 'int', 'staff_id' => 'int', 'user_id' => 'int', 'created_at' => 'datetime', 'updated_at' => 'datetime', ]; public static array $validationRules = [ 'request_id' => 'required|int', 'mood' => 'required|string|max:8', 'note' => 'nullable|string|max:1000', ]; public function request(): BelongsTo { return $this->belongsTo(StaffRequest::class, 'request_id'); } public function staff(): BelongsTo { return $this->belongsTo(User::class, 'staff_id'); } public function author(): BelongsTo { return $this->belongsTo(User::class, 'user_id'); } } 